mapper.sql:
FROM med_slot slot INNER JOIN med_schedule schedule ON schedule.id = slot.schedule_id INNER JOIN med_doctor doctor ON doctor.id = schedule.doctor_id INNER JOIN med_department department ON department.id = doctor.department_id INNER JOIN med_clinic_room room ON room.id = schedule.clinic_room_id WHERE slot.work_date = #{workDate,jdbcType=DATE} AND schedule.status = 'PUBLISHED' AND slot.work_date = schedule.work_date AND doctor.status = 'ENABLED' AND department.status = 'ENABLED' AND room.status = 'ENABLED' AND room.department_id = doctor.department_id AND slot.status = 'OPEN' AND slot.remaining_capacity > 0 AND slot.booking_deadline > #{now,jdbcType=TIMESTAMP} AND TIMESTAMP(slot.work_date, slot.start_time) > #{now,jdbcType=TIMESTAMP}
AND doctor.department_id = #{departmentId}
AND doctor.id = #{doctorId}
